package com.aaliyun.leadnews.ai;import com.aaliyun.leadnews.ai.exception.AiExceptions;import com.aaliyun.leadnews.ai.support.StructuredOutputParser;import com.aaliyun.leadnews.model.ai.StructuredModerationResult;import jakarta.validation.Validation;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThatThrownBy;
class OutputParseFailureTest {@Test void rejectsPlainTextMissingFieldsUnknownDecisionAndInvalidConfidence(){try(var f=Validation.buildDefaultValidatorFactory()){var p=new StructuredOutputParser(f.getValidator());for(String value:new String[]{"PASS","{\"decision\":\"PASS\"}","{\"decision\":\"UNKNOWN\",\"riskLevel\":\"L\",\"reason\":\"x\",\"confidence\":.5,\"riskTags\":[]}","{\"decision\":\"PASS\",\"riskLevel\":\"L\",\"reason\":\"x\",\"confidence\":2,\"riskTags\":[]}"})assertThatThrownBy(()->p.parse(value,StructuredModerationResult.class)).isInstanceOf(AiExceptions.OutputParse.class);}}}
